// The V2 admin page with S2 rendered in jsdom: useIms() is the mapped mock (test/web/__mocks__/admin-ui-web.js),
// fetch is faked per test, config.json (generated by `aio app build`) is a virtual mock.
import { act, render, screen, waitFor, within } from '@testing-library/react'
import { useIms } from '@adobe/aio-commerce-lib-admin-ui/web'
import { MainPage } from '#web/pages/main-page.tsx'
import { StuckAlerts } from '#web/components/StuckAlerts.tsx'
import { Deliveries } from '#web/components/Deliveries.tsx'

jest.mock('../../src/commerce-backend-ui-2/web-src/src/config.json', () => ({
  'StuckOrders/list-alerts': 'https://actions.test/list-alerts',
  'StuckOrders/mark-handled': 'https://actions.test/mark-handled',
  'StuckOrders/list-deliveries': 'https://actions.test/list-deliveries',
  'StuckOrders/retry-delivery': 'https://actions.test/retry-delivery'
}), { virtual: true })

const mockedUseIms = useIms as jest.Mock
const ims = { imsToken: 'test-token', imsOrgId: 'TESTORG@AdobeOrg' }

function reply (status: number, body: string) {
  return { ok: status >= 200 && status < 300, status, text: async () => body }
}

// A fake action backend: each URL answers from the routes table (a function gets the parsed body).
function fakeBackend (routes: Record<string, (body: any) => { status: number, body: string }>) {
  const fetchMock = jest.fn(async (url: string, opts: any) => {
    const name = url.replace('https://actions.test/', '')
    const route = routes[name]
    if (!route) throw new Error(`unexpected call to ${url}`)
    const { status, body } = route(JSON.parse(opts.body))
    return reply(status, body)
  })
  global.fetch = fetchMock as unknown as typeof fetch
  return fetchMock
}

const json = (data: unknown) => ({ status: 200, body: JSON.stringify(data) })
const calledActions = (fetchMock: jest.Mock) => fetchMock.mock.calls.map(([url]) => url.replace('https://actions.test/', ''))
const bodyRows = () => screen.getAllByRole('row').slice(1) // the first row is the header

afterEach(() => mockedUseIms.mockReset().mockReturnValue({ data: ims, error: null }))

describe('MainPage', () => {
  test('useIms() error: a visible "Open this inside the Commerce admin." message, no action call', () => {
    const fetchMock = fakeBackend({})
    mockedUseIms.mockReturnValue({ data: null, error: new Error('No host provides IMS credentials') })
    render(<MainPage />)
    expect(screen.getByText(/Open this inside the Commerce admin\./)).toBeTruthy()
    expect(screen.getByText(/No host provides IMS credentials/)).toBeTruthy()
    expect(fetchMock).not.toHaveBeenCalled()
  })

  test('with IMS: two tabs, the alerts tab loads with the IMS header pair', async () => {
    const fetchMock = fakeBackend({ 'list-alerts': () => json([]), 'list-deliveries': () => json([]) })
    render(<MainPage />)
    expect(screen.getByRole('tab', { name: 'Stuck orders' })).toBeTruthy()
    expect(screen.getByRole('tab', { name: 'Deliveries' })).toBeTruthy()
    await screen.findByText('No open alerts')
    const [url, opts] = fetchMock.mock.calls[0]
    expect(url).toBe('https://actions.test/list-alerts')
    expect(opts.headers.Authorization).toBe('Bearer test-token')
    expect(opts.headers['x-gw-ims-org-id']).toBe('TESTORG@AdobeOrg')
  })

  test('the Deliveries tab shows the deliveries table', async () => {
    fakeBackend({ 'list-alerts': () => json([]), 'list-deliveries': () => json([{ order: '9', status: 'dead', attempts: 3, lastError: 'ERP 500', at: '2027-01-01T00:00:00.000Z' }]) })
    render(<MainPage />)
    await screen.findByText('No open alerts')
    await act(async () => screen.getByRole('tab', { name: 'Deliveries' }).click())
    expect(await screen.findByRole('button', { name: 'Retry' })).toBeTruthy()
  })
})

describe('StuckAlerts', () => {
  test('lists alerts newest first, whatever order the action returns', async () => {
    fakeBackend({
      'list-alerts': () => json([
        { order: '100', status: 'pending_payment', created_at: '2027-01-01 08:00:00', at: '2027-01-02T00:00:00.000Z' },
        { order: '300', status: 'pending_payment', created_at: '2027-01-01 08:00:00', at: '2027-01-04T00:00:00.000Z' },
        { order: '200', status: 'pending_payment', created_at: '2027-01-01 08:00:00', at: '2027-01-03T00:00:00.000Z' }
      ])
    })
    render(<StuckAlerts ims={ims} />)
    await screen.findByText('300')
    expect(bodyRows().map(r => within(r).getByRole('rowheader').textContent)).toEqual(['300', '200', '100'])
  })

  test('Mark handled posts the order, then lists again (the handled alert is gone)', async () => {
    let open = [{ order: '7', at: '2027-01-02T00:00:00.000Z' }, { order: '8', at: '2027-01-01T00:00:00.000Z' }]
    const fetchMock = fakeBackend({
      'list-alerts': () => json(open),
      'mark-handled': (body) => { open = open.filter(a => a.order !== body.order); return json({ ok: true }) }
    })
    render(<StuckAlerts ims={ims} />)
    await screen.findByText('7')
    const row7 = bodyRows().find(r => within(r).queryByText('7'))!
    await act(async () => within(row7).getByRole('button', { name: 'Mark handled' }).click())
    await waitFor(() => expect(screen.queryByText('7')).toBeNull())
    expect(screen.getByText('8')).toBeTruthy()
    expect(calledActions(fetchMock)).toEqual(['list-alerts', 'mark-handled', 'list-alerts'])
    expect(JSON.parse(fetchMock.mock.calls[1][1].body)).toEqual({ order: '7' })
  })

  test('an HTML gateway error on list shows "Something went wrong: HTTP 502" and the empty table', async () => {
    fakeBackend({ 'list-alerts': () => ({ status: 502, body: '<!DOCTYPE html><html><body>Bad Gateway</body></html>' }) })
    render(<StuckAlerts ims={ims} />)
    expect(await screen.findByText('Something went wrong: HTTP 502')).toBeTruthy()
    expect(screen.getByText('No open alerts')).toBeTruthy()
  })
})

describe('Deliveries', () => {
  const rows = [
    { order: '9', status: 'dead', attempts: 3, lastError: 'ERP 500', at: '2027-01-02T00:00:00.000Z' },
    { order: '5', status: 'sent', attempts: 1, at: '2027-01-01T00:00:00.000Z' }
  ]

  test('Retry only on dead rows; Retry posts the order, then lists again', async () => {
    const fetchMock = fakeBackend({ 'list-deliveries': () => json(rows), 'retry-delivery': () => json({ ok: true }) })
    render(<Deliveries ims={ims} />)
    await screen.findByText('ERP 500')
    expect(screen.getAllByRole('button', { name: 'Retry' })).toHaveLength(1)
    await act(async () => screen.getByRole('button', { name: 'Retry' }).click())
    await waitFor(() => expect(calledActions(fetchMock)).toEqual(['list-deliveries', 'retry-delivery', 'list-deliveries']))
    expect(JSON.parse(fetchMock.mock.calls[1][1].body)).toEqual({ order: '9' })
  })

  test('Retry answered by an HTML gateway page shows its error text', async () => {
    fakeBackend({ 'list-deliveries': () => json(rows), 'retry-delivery': () => ({ status: 502, body: '<html>Bad Gateway</html>' }) })
    render(<Deliveries ims={ims} />)
    await screen.findByText('ERP 500')
    await act(async () => screen.getByRole('button', { name: 'Retry' }).click())
    expect(await screen.findByText('Something went wrong: HTTP 502')).toBeTruthy()
  })

  test('Retry refused with a JSON error shows that error text', async () => {
    fakeBackend({ 'list-deliveries': () => json(rows), 'retry-delivery': () => ({ status: 403, body: '{"error":"client not allowed"}' }) })
    render(<Deliveries ims={ims} />)
    await screen.findByText('ERP 500')
    await act(async () => screen.getByRole('button', { name: 'Retry' }).click())
    expect(await screen.findByText('Something went wrong: client not allowed')).toBeTruthy()
  })
})
